// Khai báo ITM Print

	int _write(int file, char *ptr, int len) {
		for (int i = 0; i < len; i++) {
			ITM_SendChar((*ptr++));
		}
		return len;
	}


// Khai báo callback EXTI

	void callback_function(void) {
		printf("Callback function called successfully.\n");
	}

// Thực thi chương trình

	int main() {

		LOG_D("Main", "System initialization started.");

		// Kiểm tra reset flag

			RCC_RSTFLG_Typedef reset_source;
			RST_SRC_Capture(&reset_source);

			LOG_D("Main", "Captured reset source flags: PinReset=%u, PorReset=%u, SftReset=%u, IwdgReset=%u, WwdgReset=%u, LowPwrReset=%u",
				reset_source.IsPinReset,
				reset_source.IsPorReset,
				reset_source.IsSftReset,
				reset_source.IsIwdgReset,
				reset_source.IsWwdgReset,
				reset_source.IsLowPwrReset
			);

			if (reset_source.IsIwdgReset == SET) {
				printf("Main: System reset caused by Independent Watchdog (IWDG).\n");
			} else if (reset_source.IsWwdgReset == SET) {
				printf("Main: System reset caused by Window Watchdog (WWDG).\n");
			} else if (reset_source.IsSftReset == SET) {
				printf("Main: System reset caused by Software Reset (SFT).\n");
			} else if (reset_source.IsPorReset == SET) {
				printf("Main: System reset caused by Power-On Reset (POR).\n");
			} else if (reset_source.IsPinReset == SET) {
				printf("Main: System reset caused by External Pin Reset (NRST pin).\n");
			} else if (reset_source.IsLowPwrReset == SET) {
				printf("Main: System reset caused by Low Power Reset.\n");
			} else {
				printf("Main: System reset source is unknown.\n");
			}

			/**
         * Ghi chú: 
         * Trong các thiết kế trước,
         * IWDG được sử dụng như 1 giải pháp đảm bảo an toàn,
         * tuy nhiên, sau khi thực hiện HIL test thì
         * IWDG không cần khởi động vì hệ thống tự động chọn HWDG để đảm bảo an toàn cho toàn hệ thống.
         */

		// Khởi động clock

			RCC_CLK_Init_Param clk_init_param = {
				.CLK_Source = RCC_SYSCLK_SOURCE_HSI
			};

			RCC_RDYFLG_Typdef clk_rdy_flg;

			if (!__OK_CHECK(RCC_CLK_Init(&clk_init_param, &clk_rdy_flg))) {
				LOG_E("Main", "Clock initialization failed.");
				return -1;
			}

		// Khởi động mẫu GPIO kèm theo cấu hình ngắt AFIO, EXTI và NVIC

			RCC_PCLK_Enable(GPIOB); // Bật clock cho GPIOB

			GPIO_Init_Param gpio_init_param = {
				.Pin = GPIO_PIN_11,
				.Mode = GPIO_MODE_INPUT_PU_PD,
				.Pull = GPIO_PULLUP,
				.Trigger = GPIO_TRIGGER_RISING
			};

			if (!__DONE_CHECK(GPIO_Init(GPIOB_REGS_PTR,&gpio_init_param))) {
				LOG_E("Main", "GPIO initialization failed.");
				return -1;
			}

			RCC_PCLK_Enable(AFIO); // Bật clock

			AFIO_EXTI_Init_Param afio_exti_init_param = {
				.Port = AFIO_EXTICR_PORTB,
				.Pin = gpio_init_param.Pin,
				.Line = 15u // Giá trị mặc định, sẽ được cập nhật trong hàm AFIO_EXTI_Line_Init
			};

			if (!__DONE_CHECK(AFIO_EXTI_Line_Init(&afio_exti_init_param))) {
				LOG_E("Main", "AFIO EXTI line initialization failed.");
				return -1;
			}

			if (!__DONE_CHECK(EXTI_Config_Init(&gpio_init_param, &afio_exti_init_param))) {
				LOG_E("Main", "EXTI configuration initialization failed.");
				return -1;
			}

			EXTI_Handle_Param exti_handle_param = {
				.Line = afio_exti_init_param.Line, // Giá trị mặc định, sẽ được cập nhật trong hàm AFIO_EXTI_Line_Init
				.Callback = callback_function // Đăng ký callback cho ngắt EXTI
			};

			if (!__DONE_CHECK(EXTI_RegisterParam(&exti_handle_param))) {
				LOG_E("Main", "EXTI parameter registration failed.");
				return -1;
			}


			NVIC_INTR_Param nvic_init_param = {
					.Position = NVIC_IRQ_POS_EXTI15_10,
					.Priority = 5,
					.Status = INTR_STAT_ENABLE
			};

			if (!__DONE_CHECK(NVIC_INTR_Config(&nvic_init_param))) {
				LOG_E("Main", "NVIC configuration initialization failed.");
				return -1;
			}

			ui32 nvic_activation = NVIC_INTR_GetActivation(NVIC_IRQ_POS_EXTI15_10);
			LOG_D("Main", "NVIC activation status for EXTI15_10 - %s.", (nvic_activation == SET) ? "Enabled" : "Disabled");

		// Vòng lặp chính

			while (1) {
				// Thực thi các tác vụ chính của ứng dụng tại đây
				LOG_D("Main", "Main loop executed.");
			}

		return 0;
	}
